\begin{tikzpicture}[line cap=round,line join=round]
% Scale from raw books to visual height: s = 0.09375 (so 64 -> 6)
% Group values: 1:28, 2:64, 3:38, 4:52, 5:48, 6:42, 7:56, 8:62, 9:18, 10:22
% Heights (value * s): 2.625, 6, 3.5625, 4.875, 4.5, 3.9375, 5.25, 5.8125, 1.6875, 2.0625

% Axes
\draw[->] (0,0) -- (11,0) node[right] {}; % x-axis
\draw[->] (0,0) -- (0,7.2) node[above, xshift=2pt]{\small Number of books}; % y-axis

% Y ticks and labels (mapped to raw values 0,20,40,60)
\foreach \y/\lbl in {0/0,1.875/20,3.75/40,5.625/60} {
  \draw (0,\y) -- (-0.15,\y) node[left, xshift=-2pt]{\small \lbl};
}

% X ticks and group labels
\foreach \i in {1,...,10} {
  \draw (\i,0) -- (\i,-0.12) node[below,yshift=-2pt]{\small \i};
}

% Bars (centered at x = 1..10, width = 0.7)
\filldraw[fill=blue!40,draw=black] (1-0.35,0) rectangle (1+0.35,2.625) node[pos=0.5]{};
\filldraw[fill=blue!40,draw=black] (2-0.35,0) rectangle (2+0.35,6) node[pos=0.5]{};
\filldraw[fill=blue!40,draw=black] (3-0.35,0) rectangle (3+0.35,3.5625) node[pos=0.5]{};
\filldraw[fill=blue!40,draw=black] (4-0.35,0) rectangle (4+0.35,4.875) node[pos=0.5]{};
% Highlight group 5 for clarity
\filldraw[fill=orange!60,draw=black] (5-0.35,0) rectangle (5+0.35,4.5) node[pos=0.5]{};
\filldraw[fill=blue!40,draw=black] (6-0.35,0) rectangle (6+0.35,3.9375) node[pos=0.5]{};
\filldraw[fill=blue!40,draw=black] (7-0.35,0) rectangle (7+0.35,5.25) node[pos=0.5]{};
\filldraw[fill=blue!40,draw=black] (8-0.35,0) rectangle (8+0.35,5.8125) node[pos=0.5]{};
\filldraw[fill=blue!40,draw=black] (9-0.35,0) rectangle (9+0.35,1.6875) node[pos=0.5]{};
\filldraw[fill=blue!40,draw=black] (10-0.35,0) rectangle (10+0.35,2.0625) node[pos=0.5]{};

% Numeric labels above each bar (actual counts)
\node at (1,2.625+0.12) {\scriptsize 28};
\node at (2,6+0.12) {\scriptsize 64};
\node at (3,3.5625+0.12) {\scriptsize 38};
\node at (4,4.875+0.12) {\scriptsize 52};
\node at (5,4.5+0.12) {\scriptsize 48};
\node at (6,3.9375+0.12) {\scriptsize 42};
\node at (7,5.25+0.12) {\scriptsize 56};
\node at (8,5.8125+0.12) {\scriptsize 62};
\node at (9,1.6875+0.12) {\scriptsize 18};
\node at (10,2.0625+0.12) {\scriptsize 22};

% Subtle baseline line for clarity
\draw[dashed, gray!40] (0,0) -- (11,0);

\end{tikzpicture}

